import * as THREE from 'three';
import {createMapEditor,validateMapEdits,biomeValues,MAP_FORMAT} from './editor-core.js?v=27.1';
const KEY='silvengard-map-edits-v1',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createPainting({D,world,point,canvas,controls,locate,preview,refresh,toast,biomeNames,changeMode,beforeOpen,beforeStroke}){
 const model=createMapEditor(D);let saved=null;try{const raw=localStorage.getItem(KEY);if(raw){saved=validateMapEdits(JSON.parse(raw),D);model.importData(saved);const pending=model.exportData();saved=pending;if(!pending.cells.length)localStorage.setItem(KEY,JSON.stringify(pending));}}catch(e){toast('Edição do mapa não carregada: '+e.message);}
 canvas.tabIndex=0;let active=false,drawing=false,kind='state',radius=12,lastPoint=null,changedIds=new Set(),scheduled=false,owner=13,biome=6,density=.7,species='conifer',culture=11,religion=31;
 const panel=document.createElement('aside');panel.id='mapEditor';panel.hidden=true;panel.setAttribute('aria-label','Editor do mapa');document.body.append(panel);
 panel.innerHTML=`<div class="editorHeading"><div><div class="eyebrow">EDIÇÃO DO AUTOR</div><h2>Pincéis do mapa</h2></div><button id="closeEditor" title="Fechar editor">×</button></div><div class="editorBody"><div class="editorTabs"><button data-brush="state" class="active">Político</button><button data-brush="biome">Bioma</button><button data-brush="vegetation">Vegetação</button><button data-brush="culture">Cultura</button><button data-brush="religion">Religião</button></div><label class="editorSwitch"><input id="paintEnabled" type="checkbox"> Pintar no mapa</label><p class="source">Com o pincel ligado, arraste o botão esquerdo para pintar. Use o botão direito, a roda ou WASD para navegar. Esc desliga o pincel.</p><label>Tamanho do pincel · <output id="brushRadiusValue">12</output><input id="brushRadius" type="range" min="3" max="60" step="1" value="12"></label><div data-options="state"><label>Transferir território para<select id="brushState">${D.states.map(s=>`<option value="${s.i}" ${s.i===13?'selected':''}>${esc(s.i?s.name.trim():'Terras neutras')}</option>`).join('')}</select></label><p class="source">Pinta a propriedade do território. As fronteiras, a área e as cidades atingidas acompanham a mudança. As ilhas e costas permanecem no lugar.</p></div><div data-options="biome" hidden><label>Bioma<select id="brushBiome">${biomeNames.map((s,i)=>i>0&&i!==16?`<option value="${i}" ${i===6?'selected':''}>${esc(s)}</option>`:'').join('')}</select></label><p class="source">Altera a cor do solo, o clima visual e a vegetação típica. Para ajustar só as árvores, use Vegetação.</p></div><div data-options="vegetation" hidden><label>Tipo de vegetação<select id="brushSpecies"><option value="conifer">Pinheiros temperados</option><option value="broadleaf">Árvores de folhas largas</option><option value="dead">Floresta morta</option><option value="tropical">Árvores tropicais</option><option value="acacia">Acácias</option><option value="auto">Conforme o bioma</option><option value="none">Sem árvores</option></select></label><label>Densidade · <output id="brushDensityValue">70%</output><input id="brushDensity" type="range" min="0" max="200" step="5" value="70"></label><p class="source">100% corresponde à densidade típica de uma floresta. Cidades e rios mantêm pequenas clareiras. O bioma do solo permanece igual.</p></div><div data-options="culture" hidden><label>Cultura da região<select id="brushCulture"><option value="-1">Automático · seguir as cidades</option>${D.cultures.map(c=>`<option value="${c.i}" ${c.i===11?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="source">A escolha pintada tem prioridade nesta área. Selecione Automático para voltar a acompanhar as cidades. A ficha de cada cidade permanece independente.</p></div><div data-options="religion" hidden><label>Religião da região<select id="brushReligion"><option value="-1">Automático · seguir as cidades</option>${D.religions.map(r=>`<option value="${r.i}" ${r.i===31?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><p class="source">Pinte uma religião ou selecione Automático para restaurar a distribuição pelas cidades. A divindade acompanha a religião escolhida.</p></div><div class="editorActions"><button id="undoPaint">↶ Desfazer</button><button id="redoPaint">↷ Refazer</button></div><p id="paintStatus" role="status"></p><button id="exportMapEdits" class="editorPrimary">Exportar alterações do mapa ↓</button><label class="editorImport">Importar alterações<input id="importMapEdits" type="file" accept="application/json" hidden></label><button id="restoreMap">Restaurar mapa original…</button><p class="source">Salvo neste navegador. O JSON inclui as células e os valores alterados: use “Definir como padrão” para guardar no Atlas, ou exporte uma cópia de segurança. “Exportar edição”, no rodapé, também inclui os pincéis, as fichas e as jornadas. Pincéis atuam somente em terra.</p></div>`;
 const $=s=>panel.querySelector(s),ring=new THREE.LineLoop(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#ffd47e',depthTest:false,transparent:true,opacity:.9}));ring.renderOrder=20;ring.visible=false;world.add(ring);
 function cursor(xy){if(!active||!xy){ring.visible=false;preview([]);return;}const positions=[];for(let i=0;i<80;i++){const a=i/80*Math.PI*2;positions.push(point(xy[0]+Math.cos(a)*radius,xy[1]+Math.sin(a)*radius,1.6));}ring.geometry.dispose();ring.geometry=new THREE.BufferGeometry().setFromPoints(positions);ring.visible=true;preview([]);}
 function status(){const n=model.exportData().cells.length;$('#paintStatus').textContent=`${n.toLocaleString('pt-BR')} células alteradas · ${active?'pincel ligado':'pincel desligado'}`;$('#undoPaint').disabled=!model.canUndo;$('#redoPaint').disabled=!model.canRedo;}
 function persist(){try{localStorage.setItem(KEY,JSON.stringify(model.exportData()));}catch{toast('Não foi possível salvar no navegador. Exporte as alterações para guardar sua edição.');}status();}
 function setActive(value){active=!!value;$('#paintEnabled').checked=active;canvas.style.cursor=active?'crosshair':'grab';if(!active){finish();ring.visible=false;preview([]);}status();}
 function commit(ids){if(!ids.length)return;refresh(ids);persist();}
 function finish(){if(!drawing)return;drawing=false;controls.enabled=true;lastPoint=null;const ids=model.end();changedIds.clear();commit(ids);}
 function values(){return kind==='culture'?{cultureOverride:culture}:kind==='religion'?{religionOverride:religion}:kind==='state'?{state:owner}:kind==='biome'?biomeValues(biome):{woodland:species==='none'?0:density,vegetation:species};}
 function dab(xy){const from=lastPoint||xy,steps=Math.max(1,Math.ceil(Math.hypot(xy[0]-from[0],xy[1]-from[1])/Math.max(1,radius*.35)));for(let i=1;i<=steps;i++)for(const id of model.paint(from[0]+(xy[0]-from[0])*i/steps,from[1]+(xy[1]-from[1])*i/steps,radius,values()))changedIds.add(id);lastPoint=xy;if(!scheduled){scheduled=true;requestAnimationFrame(()=>{scheduled=false;if(changedIds.size)preview([...changedIds]);});}}
 canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();const xy=locate(e);if(!xy){toast('Pinte em terra; costa e água são preservadas.');return;}canvas.focus({preventScroll:true});beforeStroke();drawing=true;controls.enabled=false;model.begin();canvas.setPointerCapture(e.pointerId);dab(xy);cursor(xy);},{capture:true});
 canvas.addEventListener('pointermove',e=>{if(!active)return;if(!drawing&&e.buttons){ring.visible=false;preview([]);return;}e.stopImmediatePropagation();const xy=locate(e);cursor(xy);if(drawing){e.preventDefault();if(xy)dab(xy);else lastPoint=null;}},{capture:true});
 const end=e=>{if(!drawing){if(active&&e.button===0){e.preventDefault();e.stopImmediatePropagation();}return;}e.preventDefault();e.stopImmediatePropagation();if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);finish();};canvas.addEventListener('pointerup',end,{capture:true});canvas.addEventListener('pointercancel',end,{capture:true});canvas.addEventListener('lostpointercapture',finish);canvas.addEventListener('pointerleave',()=>{ring.visible=false;preview([]);});addEventListener('blur',finish);
 $('#paintEnabled').onchange=e=>{setActive(e.target.checked);if(active)canvas.focus({preventScroll:true});};$('#closeEditor').onclick=()=>{setActive(false);panel.hidden=true;};$('#brushRadius').oninput=e=>{radius=+e.target.value;$('#brushRadiusValue').value=radius;};$('#brushDensity').oninput=e=>{density=+e.target.value/100;$('#brushDensityValue').value=e.target.value+'%';};$('#brushCulture').onchange=e=>culture=+e.target.value;$('#brushReligion').onchange=e=>religion=+e.target.value;$('#brushState').onchange=e=>owner=+e.target.value;$('#brushBiome').onchange=e=>biome=+e.target.value;$('#brushSpecies').onchange=e=>species=e.target.value;
 panel.querySelectorAll('[data-brush]').forEach(b=>b.onclick=()=>{kind=b.dataset.brush;panel.querySelectorAll('[data-brush]').forEach(el=>el.classList.toggle('active',el===b));panel.querySelectorAll('[data-options]').forEach(el=>el.hidden=el.dataset.options!==kind);changeMode(kind==='state'?'political':['culture','religion'].includes(kind)?kind:'natural');});
 $('#undoPaint').onclick=()=>{finish();commit(model.undo());status();};$('#redoPaint').onclick=()=>{finish();commit(model.redo());status();};
 function download(){finish();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({...model.exportData(),exportedAt:new Date().toISOString(),legend:{states:D.states.map(s=>({i:s.i,name:s.name})),biomes:biomeNames}},null,2)],{type:'application/json'}));a.download='silvengard-alteracoes-mapa.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Alterações do mapa exportadas');}$('#exportMapEdits').onclick=download;
 function importData(raw){finish();const clean=validateMapEdits(raw,D);commit(model.importData(clean));persist();}
 $('#importMapEdits').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('Arquivo muito grande');const raw=JSON.parse(await f.text());importData(raw.mapEdits||raw);toast('Alterações do mapa importadas');}catch(err){toast('Não foi possível importar: '+err.message);}finally{e.target.value='';}};
 $('#restoreMap').onclick=()=>{const d=document.createElement('dialog');d.className='journeyConfirm';d.innerHTML='<form method="dialog"><h2>Restaurar mapa original?</h2><p>Remove as pinceladas locais. Você poderá desfazer esta ação. Fichas e jornadas são preservadas.</p><div class="editorActions"><button value="cancel">Cancelar</button><button value="yes">Restaurar</button></div></form>';document.body.append(d);d.addEventListener('close',()=>{if(d.returnValue==='yes')importData({format:MAP_FORMAT,baseRevision:D.revision,grid:D.grid,cells:[]});d.remove();},{once:true});d.showModal();};
 addEventListener('keydown',e=>{if(panel.hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='Escape')setActive(false);if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();finish();commit(e.key.toLowerCase()==='y'||e.shiftKey?model.redo():model.undo());status();}});
 status();return {setCityBiome(id,biome){finish();const c=D.cells[id];model.begin();model.paint(...c.p,.1,biomeValues(biome));commit(model.end());},open(){beforeOpen();panel.hidden=false;changeMode(kind==='state'?'political':['culture','religion'].includes(kind)?kind:'natural');status();},close(){setActive(false);panel.hidden=true;},get active(){return active;},get drawing(){return drawing;},exportData(){finish();return model.exportData();},importData,restored:saved?.cells.length? saved.cells.map(c=>c.i):[]};
}
